<?php $pageTitle='Dashboard';$subtitle='A live view of products, orders, employees and field operations.';$active='Dashboard';require __DIR__.'/_layout.php';
$pdo=db();$stats=[];foreach([['Products','SELECT COUNT(*) FROM products WHERE status="active"'],['Orders','SELECT COUNT(*) FROM orders'],['Revenue','SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE order_status<>"cancelled"'],['Employees','SELECT COUNT(*) FROM users WHERE role="employee" AND status="active"'],['Pending Attendance','SELECT COUNT(*) FROM attendance WHERE status="pending"']] as $x){$q=$pdo->query($x[1]);$stats[]=[ $x[0],$q->fetchColumn()];}
$recent=$pdo->query('SELECT order_number,customer_name,total_amount,payment_status,order_status,created_at FROM orders ORDER BY created_at DESC LIMIT 8')->fetchAll();$work=$pdo->query("SELECT ea.*,u.name employee_name FROM employee_assignments ea JOIN users u ON u.id=ea.employee_id WHERE ea.status NOT IN ('completed','cancelled') ORDER BY ea.created_at DESC LIMIT 6")->fetchAll();
?>
<div class="grid stats"><?php foreach($stats as $s):?><div class="card stat"><div class="label"><?=ae($s[0])?></div><strong><?= $s[0]==='Revenue'?'₹'.number_format((float)$s[1],2):number_format((int)$s[1])?></strong><small>Live database</small></div><?php endforeach;?></div><div class="grid two" style="margin-top:18px"><section class="card"><div class="section-head"><h2>Recent Orders</h2><a class="btn" href="orders.php">View all</a></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><strong><?=ae($r['order_number'])?></strong><br><small><?=ae($r['created_at'])?></small></td><td><?=ae($r['customer_name'])?></td><td>₹<?=number_format((float)$r['total_amount'],2)?></td><td><span class="pill gold"><?=ae(strtoupper($r['payment_status']))?></span></td><td><span class="pill blue"><?=ae(strtoupper($r['order_status']))?></span></td></tr><?php endforeach;if(!$recent):?><tr><td colspan="5" class="empty">No orders yet.</td></tr><?php endif;?></tbody></table></div></section><section class="card"><div class="section-head"><h2>Open Assignments</h2><a class="btn" href="assignments.php">Manage</a></div><?php foreach($work as $w):?><div style="padding:13px 0;border-bottom:1px solid var(--line)"><strong><?=ae($w['title'])?></strong><div style="color:var(--muted);font-size:12px;margin-top:5px"><?=ae($w['employee_name'])?> · <?=ae($w['assignment_type'])?> · <?=ae($w['priority'])?></div></div><?php endforeach;if(!$work):?><div class="empty">No open assignments.</div><?php endif;?></section></div>
<?php require __DIR__.'/_foot.php'; ?>
